/**
 * Saves the tasks, replacing what was saved before.
 * @param {readonly import("./task-store.js").Task[]} tasks
 * @param {Storage} [storage] localStorage, unless a test passes another
 * @returns {boolean} false when the browser refused, because storage is full or blocked
 */
export function saveTasks(tasks, storage) {
  try {
    const target = storage ?? localStorage;
    target.setItem(STORAGE_KEY, JSON.stringify(tasks.map(pick)));
    return true;
  } catch {
    return false;
  }
}

/**
 * Reads the saved tasks.
 * @param {Storage} [storage] localStorage, unless a test passes another
 * @returns {import("./task-store.js").Task[] | null} the tasks, or null when nothing usable is saved
 */
export function loadTasks(storage) {
  let raw;
  try {
    // Even reading can throw, when the browser blocks storage for this page.
    raw = (storage ?? localStorage).getItem(STORAGE_KEY);
  } catch {
    return null;
  }
  if (raw === null) return null;

  try {
    const data = JSON.parse(raw);
    if (Array.isArray(data) && data.every(isTask)) return data.map(pick);
  } catch {
    // Not JSON at all: treated below like any other data of the wrong shape.
  }
  console.warn(`Ignoring saved tasks that are not in the ${STORAGE_KEY} shape.`);
  return null;
}

describe("loadTasks with bad data", () => {
  it.each([
    ["text that is not JSON", "{not json"],
    ["JSON that is not a list", '{"tasks":[]}'],
    ["a task without a title", '[{"id":"a","done":false}]'],
    ["a task whose done is a string", '[{"id":"a","title":"Buy milk","done":"no"}]'],
  ])("returns null for %s, with a warning", (_, saved) => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    const storage = new MemoryStorage();
    storage.setItem(STORAGE_KEY, saved);
    expect(loadTasks(storage)).toBeNull();
    expect(warn).toHaveBeenCalledOnce();
    warn.mockRestore();
  });

  it("returns null when the browser blocks storage", () => {
    expect(loadTasks(refusingStorage)).toBeNull();
  });
});

/** The part of the Storage interface persist.js uses, kept in a Map. */
class MemoryStorage {
  #items = new Map();

  getItem(key) {
    return this.#items.get(key) ?? null;
  }

  setItem(key, value) {
    this.#items.set(key, String(value));
  }
}

/** A storage that refuses every call, as a browser does when storage is full or blocked. */
const refusingStorage = {
  getItem() {
    throw new DOMException("The operation is insecure.", "SecurityError");
  },
  setItem() {
    throw new DOMException("The quota has been exceeded.", "QuotaExceededError");
  },
};

describe("saveTasks and loadTasks", () => {
  it("save under tasks:v1 and load the same tasks back", () => {
    const storage = new MemoryStorage();
    expect(saveTasks(tasks, storage)).toBe(true);
    expect(JSON.parse(storage.getItem(STORAGE_KEY))).toEqual(tasks);
    expect(loadTasks(storage)).toEqual(tasks);
  });

  it("save only the fields a task has", () => {
    const storage = new MemoryStorage();
    saveTasks([{ ...tasks[0], editing: true }], storage);
    expect(loadTasks(storage)).toEqual([tasks[0]]);
  });

  it("load null when nothing is saved", () => {
    expect(loadTasks(new MemoryStorage())).toBeNull();
  });
});

const port = Number(process.env.PORT) || 5173;

export default defineConfig({
  // Vite's own cache lives here instead of node_modules/.vite, because the
  // workspace shares node_modules between projects and mounts it read-only.
  cacheDir: ".vite-cache",
  server: {
    // 0.0.0.0 listens on every network interface, not only on loopback, so the
    // server can be reached from outside its container.
    host: "0.0.0.0",
    port,
    // Stop with an error instead of quietly moving to a port nobody is watching.
    strictPort: true,
  },
  preview: {
    host: "0.0.0.0",
    port,
    strictPort: true,
  },
});
